package com.lexiscan.document; import com.lexiscan.user.User; import jakarta.persistence.*; import lombok.*; import java.time.*; import java.util.*;
@Entity @Table(name="documents") @Getter @Setter @NoArgsConstructor public class Document { @Id private UUID id=UUID.randomUUID(); @ManyToOne(optional=false) @JoinColumn(name="user_id") private User user; @Column(name="file_name") private String fileName; @Column(name="stored_path") private String storedPath; @Column(name="file_type") private String fileType; @Column(name="file_size") private long fileSize; @Enumerated(EnumType.STRING) private DocumentStatus status=DocumentStatus.UPLOADED; @Column(name="failure_reason") private String failureReason; @Column(name="uploaded_at") private Instant uploadedAt=Instant.now(); @Column(name="analyzed_at") private Instant analyzedAt; }
